import { Component, ViewEncapsulation, AfterViewInit, OnDestroy, Renderer2 } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-top-page',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './top-page.component.html',
  styleUrls: ['./top-page.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class TopPageComponent implements AfterViewInit, OnDestroy {
  private loadedScripts: HTMLScriptElement[] = [];
  faqOpen: boolean[] = [false, false, false, false, false, false, false, false, false, false, false, false, false, false];

  toggleFaq(index: number): void {
    this.faqOpen[index] = !this.faqOpen[index];
  }

  constructor(private renderer: Renderer2) {}

  ngAfterViewInit(): void {
    this.loadScript('assets/js/top-main.js').then(() => {
      this.loadScript('assets/js/top-index.js');
      this.loadScript('assets/js/lazysizes.min.js');
      this.loadScript('assets/js/ls.unveilhooks.min.js');
    });
  }

  ngOnDestroy(): void {
    this.loadedScripts.forEach(script => {
      if (script.parentNode) {
        script.parentNode.removeChild(script);
      }
    });
  }

  private loadScript(src: string): Promise<void> {
    return new Promise((resolve, reject) => {
      const script = this.renderer.createElement('script');
      script.src = src;
      script.onload = () => resolve();
      script.onerror = () => reject(new Error(`Failed to load ${src}`));
      this.renderer.appendChild(document.body, script);
      this.loadedScripts.push(script);
    });
  }
}
